"""Legacy migration import; canonical table definitions live in models."""

from .migrations import MIGRATIONS
from .models import SCHEMA as SCHEMA

LEDGER_SCHEMA = """CREATE TABLE IF NOT EXISTS app_schema_migrations (
    version INTEGER PRIMARY KEY, name TEXT NOT NULL,
    applied_at TIMESTAMPTZ NOT NULL DEFAULT now())"""


def reference_schema() -> str:
    """Export reproducible schema-building SQL without connecting to any database."""
    header = (
        "-- Generated by python scripts/export_schema.py; do not edit.\n"
        "-- Review reference for an EMPTY schema, not an existing-database upgrade.\n"
        "-- Includes ordered schema definitions and revision data repairs.\n"
        "-- Does not stamp the migration ledger or describe a production installation.\n"
        "-- Apply upgrades with python scripts/migrate.py instead.\n\n"
    )
    statements = [LEDGER_SCHEMA + ";"]
    statements.extend(
        f"-- Revision {version}: {name}\n{sql.strip()}" for version, name, sql in MIGRATIONS
    )
    return header + "\n\n".join(statements) + "\n"
